-- =============================================================================
-- 461 — LE CAHIER D'EXERCICES DE 3E (partie 5)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 461 --niveau 3e --fichiers svt.m1,svt.m2 --suffixe 5 > supabase/contenu/461_exercices_3e_5.sql
--
-- 66 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   svt.m1                  33 exercices · 11 chapitres
--   svt.m2                  33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('704037d9-6f2a-5ac4-8824-00e4cff12d6e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le tableau de famille du système solaire","competence":"lire-tableau","situation":"Une revue d’astronomie publie une fiche d’identité des huit planètes. Tu t’en sers pour les ranger par famille.","documents":[{"id":"planetes","type":"tableau","titre":"Les huit planètes en chiffres","colonnes":["Planète","Diamètre (km)","Distance au Soleil (millions de km)","Densité (eau = 1)"],"lignes":[["Mercure","4 900",58,5.4],["Vénus","12 100",108,5.2],["Terre","12 700",150,5.5],["Mars","6 800",228,3.9],["Jupiter","139 800",778,1.3],["Saturne","116 500","1 430",0.7],["Uranus","50 700","2 870",1.3],["Neptune","49 200","4 500",1.6]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Lis dans le tableau la densité de la Terre.","aide":"Cherche la ligne « Terre », dernière colonne.","type":"nombre"},{"enonce":"Que remarques-tu pour les quatre planètes les plus proches du Soleil ?","aide":"Compare leur diamètre et leur densité avec ceux de Jupiter.","type":"choix","options":[{"id":"a","texte":"Elles sont petites et denses (densité supérieure à 3,5)"},{"id":"b","texte":"Elles ont toutes la même taille"},{"id":"c","texte":"Elles sont toutes moins denses que l’eau"},{"id":"d","texte":"Elles sont énormes et peu denses"}],"multiple":false},{"enonce":"Classe chaque planète dans sa famille.","aide":"Les géantes gazeuses sont Jupiter et Saturne ; les géantes glacées sont plus loin et plus froides.","type":"categories","categories":[{"id":"c0","texte":"Tellurique"},{"id":"c1","texte":"Géante gazeuse"},{"id":"c2","texte":"Géante glacée"}],"items":[{"id":"i0","texte":"Neptune"},{"id":"i1","texte":"Jupiter"},{"id":"i2","texte":"Saturne"},{"id":"i3","texte":"Mars"},{"id":"i4","texte":"Uranus"},{"id":"i5","texte":"Vénus"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":5.5,"tolerance":0},"affichage":"5,5","explication":"La densité de la Terre est de **5,5** : c’est la planète la plus dense du système solaire."},{"cle":{"type":"choix","ids":["a"]},"explication":"Mercure, Vénus, la Terre et Mars sont **petites et denses** : ce sont les planètes **telluriques**, rocheuses."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c1","i3":"c0","i4":"c2","i5":"c0"}},"explication":"Mars et Vénus sont **telluriques** ; Jupiter et Saturne **géantes gazeuses** ; Uranus et Neptune **géantes glacées**."}]$ex$::jsonb),
  ('704037d9-6f2a-5ac4-8824-00e4cff12d6e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi l’été est-il chaud à Paris ?","competence":"analyser-document","situation":"Chaque année, Paris connaît des étés chauds et des hivers froids. Un élève de 3e compare les durées du jour et la hauteur du Soleil à midi à quatre dates clés.","documents":[{"id":"jour","type":"graphique","forme":"barres","titre":"Durée du jour à Paris","categories":["21 déc.","21 mars","21 juin","21 sept."],"series":[{"nom":"Durée du jour","valeurs":[8,12,16,12],"teinte":"jaune"}],"axeY":{"titre":"Durée du jour","unite":"h","min":0,"max":18,"pas":2},"axeX":{"titre":"Date"},"valeurs":false,"source":"Valeurs arrondies à l’heure"},{"id":"soleil","type":"tableau","titre":"Hauteur du Soleil à midi à Paris","colonnes":["Date","Hauteur du Soleil à midi (°)","Saison commençant ce jour-là"],"lignes":[["21 déc.",18,"Hiver"],["21 mars",41,"Printemps"],["21 juin",65,"Été"],["21 sept.",41,"Automne"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche la barre du jour le plus long de l’année.","aide":"Cherche la barre la plus haute.","type":"zone","document":"jour","multiple":false},{"enonce":"De combien d’heures le jour du 21 juin dépasse-t-il celui du 21 décembre ?","aide":"Soustrais les deux durées lues sur le graphique.","type":"nombre","unite":"h"},{"enonce":"Comment le tableau explique-t-il que l’été chauffe davantage ?","aide":"Regarde la hauteur du Soleil à midi : plus il est haut, plus les rayons sont verticaux.","type":"choix","options":[{"id":"a","texte":"Le Soleil produit plus d’énergie en été"},{"id":"b","texte":"La Terre est plus proche du Soleil"},{"id":"c","texte":"Les rayons arrivent plus à la verticale (65°) et les jours sont plus longs"},{"id":"d","texte":"La Terre tourne plus vite sur elle-même"}],"multiple":false},{"enonce":"Début janvier, la Terre est un peu plus proche du Soleil qu’en juillet (147 contre 152 millions de km), et pourtant c’est l’hiver à Paris. Que conclure ?","aide":"Si la distance expliquait les saisons, il ferait chaud en janvier.","type":"choix","options":[{"id":"a","texte":"Les saisons dépendent de la rotation en 24 h"},{"id":"b","texte":"Les mesures de distance sont fausses"},{"id":"c","texte":"Il fait froid car la Terre ralentit"},{"id":"d","texte":"La distance au Soleil n’explique pas les saisons : c’est l’inclinaison de 23,5° de l’axe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"Le **21 juin** a le jour le plus long : 16 heures."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 h","explication":"16 − 8 = **8 heures** de jour en plus : le Soleil chauffe plus longtemps."},{"cle":{"type":"choix","ids":["c"]},"explication":"En été, le Soleil est haut (**65°**) et reste longtemps : la même énergie est répartie sur une surface plus petite et pendant plus de temps."},{"cle":{"type":"choix","ids":["d"]},"explication":"Ce sont **l’inclinaison de l’axe** et la révolution autour du Soleil qui créent les saisons, pas la distance."}]$ex$::jsonb),
  ('704037d9-6f2a-5ac4-8824-00e4cff12d6e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trois voisines, une seule habitable","competence":"raisonner","situation":"Vénus, la Terre et Mars sont toutes des planètes telluriques. Pourtant, seule la Terre accueille la vie. Tu croises deux documents pour comprendre pourquoi.","documents":[{"id":"voisines","type":"tableau","titre":"Vénus, la Terre et Mars","colonnes":["","Vénus","Terre","Mars"],"lignes":[["Distance au Soleil (millions de km)",108,150,228],["Température moyenne en surface","≈ 460 °C","15 °C","≈ −60 °C"],["Pression atmosphérique (Terre = 1)","≈ 90","1","≈ 0,006"],["Eau liquide en surface","non","oui","non"]],"enteteLignes":true,"source":"Valeurs arrondies"},{"id":"serre","type":"graphique","forme":"barres","titre":"Température moyenne de la Terre","categories":["Sans effet de serre naturel","Avec effet de serre naturel"],"series":[{"nom":"Température moyenne","valeurs":[-18,15],"teinte":"corail"}],"axeY":{"titre":"Température","unite":"°C","min":-20,"max":20,"pas":5},"valeurs":false,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche la barre de la Terre sans effet de serre naturel.","aide":"Cherche la barre sous zéro.","type":"zone","document":"serre","multiple":false},{"enonce":"Quelle est la hausse de température apportée par l’effet de serre naturel ?","aide":"Calcule 15 − (−18).","type":"nombre","unite":"°C"},{"enonce":"Vénus est plus proche du Soleil que la Terre, mais 460 °C est bien plus que sa distance ne l’explique. Quelle est la cause principale ?","aide":"Regarde la pression atmosphérique de Vénus dans le tableau.","type":"choix","options":[{"id":"a","texte":"Un effet de serre qui s’est emballé dans une atmosphère très dense"},{"id":"b","texte":"Une rotation plus rapide"},{"id":"c","texte":"Un champ magnétique trop faible"},{"id":"d","texte":"Une absence totale d’atmosphère"}],"multiple":false},{"enonce":"Pourquoi Mars est-elle si froide et sans eau liquide ?","aide":"Compare sa pression atmosphérique à celle de la Terre.","type":"choix","options":[{"id":"a","texte":"Elle a perdu presque toute son atmosphère (pression de 0,006)"},{"id":"b","texte":"Elle est trop proche du Soleil"},{"id":"c","texte":"Elle est trop petite pour tourner"},{"id":"d","texte":"Elle a un effet de serre emballé"}],"multiple":false},{"enonce":"Associe chaque planète ou condition à ce qui la caractérise.","aide":"Pense aux conditions qui rendent la Terre habitable.","type":"association","gauche":[{"id":"g0","texte":"Vénus"},{"id":"g1","texte":"Mars"},{"id":"g2","texte":"Terre"},{"id":"g3","texte":"Couche d’ozone"}],"droite":[{"id":"d0","texte":"Atmosphère perdue"},{"id":"d1","texte":"Distance qui permet l’eau liquide"},{"id":"d2","texte":"Filtre les ultraviolets"},{"id":"d3","texte":"Effet de serre emballé"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Sans effet de serre naturel, la Terre serait à **−18 °C** en moyenne : un monde gelé."},{"cle":{"type":"nombre","valeur":33,"tolerance":0},"affichage":"33 °C","explication":"15 − (−18) = **33 °C** : l’effet de serre naturel rend la Terre habitable."},{"cle":{"type":"choix","ids":["a"]},"explication":"Avec **90 fois** la pression terrestre, l’atmosphère de Vénus retient la chaleur : l’effet de serre s’est **emballé**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Mars a perdu son atmosphère : trop mince pour garder la chaleur, elle est à **−60 °C**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Vénus : emballement ; Mars : atmosphère perdue ; Terre : bonne distance au Soleil ; ozone : filtre les UV."}]$ex$::jsonb),
  ('171ce417-ed06-5aa8-b7a7-bb6ac32075f2'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"À la vitesse des ongles","competence":"lire-graphique","situation":"Les plaques lithosphériques bougent, mais lentement. Un géologue compare la vitesse de déplacement de trois plaques.","documents":[{"id":"vitesses","type":"graphique","forme":"barres-h","titre":"Vitesse de déplacement de deux plaques l’une par rapport à l’autre","categories":["Dorsale médio-atlantique (nord)","Inde vers Eurasie","Dorsale Pacifique-Est"],"series":[{"nom":"Vitesse","valeurs":[2,5,15],"teinte":"brun"}],"axeY":{"titre":"Vitesse","unite":"cm/an","min":0,"max":16,"pas":2},"valeurs":false,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche la barre du mouvement le plus rapide.","aide":"Cherche la barre la plus longue.","type":"zone","document":"vitesses","multiple":false},{"enonce":"À 2 cm par an, de combien de kilomètres l’Atlantique s’élargit-il en 1 million d’années ?","aide":"Rappel : 1 km = 100 000 cm. Calcule d’abord 2 cm × 1 000 000.","type":"nombre","unite":"km"},{"enonce":"À quoi ressemble la vitesse des plaques ?","aide":"On parle de quelques centimètres par an.","type":"choix","options":[{"id":"a","texte":"À la vitesse de pousse des ongles"},{"id":"b","texte":"À la vitesse d’un piéton"},{"id":"c","texte":"À celle du son"},{"id":"d","texte":"À celle d’une voiture sur autoroute"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"L’asthénosphère est la couche plus ductile du manteau.","type":"trous","segments":["Les plaques se déplacent de ",0," par an sur l’",1,"."],"banque":["atmosphère","quelques mètres","quelques kilomètres","asthénosphère","quelques centimètres","croûte"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"La dorsale Pacifique-Est s’écarte à environ **15 cm/an** : la plus rapide."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 km","explication":"2 cm × 1 000 000 = 2 000 000 cm = **20 km**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Quelques centimètres par an, c’est la vitesse de pousse des **ongles**."},{"cle":{"type":"trous","trous":[["quelques centimetres"],["asthenosphere"]]},"affichage":"quelques centimètres · asthénosphère","explication":"Les plaques glissent de **quelques centimètres** par an sur l’**asthénosphère**, plus ductile."}]$ex$::jsonb),
  ('171ce417-ed06-5aa8-b7a7-bb6ac32075f2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre lieux, quatre frontières","competence":"lire-carte","situation":"Quatre lieux du globe sont repérés par une lettre sur une carte. Chacun se trouve sur un type de frontière de plaques différent.","documents":[{"id":"carte","type":"carte","titre":"Quatre lieux sur des frontières de plaques","fond":"monde","lieux":[{"id":"z1","lieu":"reykjavik","symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"tokyo","symbole":"lettre","lettre":"B","teinte":"violet"},{"id":"z3","lieu":"mont-everest","symbole":"lettre","lettre":"C","teinte":"brun"},{"id":"z4","lieu":"san-francisco","symbole":"lettre","lettre":"D","teinte":"vert"}]},{"id":"obs","type":"tableau","titre":"Ce qu’on y observe","colonnes":["Repère","Observations"],"lignes":[["A","Volcans à lave fluide, séismes superficiels, roche neuve qui se forme"],["B","Fosse océanique, séismes profonds, volcans explosifs"],["C","Chaîne de montagnes, séismes, pas de volcans"],["D","Séismes, pas de volcanisme, deux plaques qui glissent"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque repère au type de frontière.","aide":"Lis les observations : volcans ? fosse ? montagnes ? glissement ?","type":"association","gauche":[{"id":"g0","texte":"A"},{"id":"g1","texte":"B"},{"id":"g2","texte":"C"},{"id":"g3","texte":"D"}],"droite":[{"id":"d0","texte":"Convergente : subduction"},{"id":"d1","texte":"Convergente : collision"},{"id":"d2","texte":"Divergente (dorsale)"},{"id":"d3","texte":"Coulissante (faille transformante)"}]},{"enonce":"Touche le lieu où deux plaques s’écartent.","aide":"Cherche la lave fluide et la lithosphère neuve.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le lieu où une plaque océanique plonge sous une autre.","aide":"Une fosse océanique marque l’endroit où elle plonge.","type":"zone","document":"carte","multiple":false},{"enonce":"Pourquoi n’y a-t-il pas de volcans au lieu D ?","aide":"Pense au mouvement des plaques en D.","type":"choix","options":[{"id":"a","texte":"Les plaques glissent l’une contre l’autre sans faire remonter de magma"},{"id":"b","texte":"Les plaques s’écartent trop vite"},{"id":"c","texte":"Il y a trop d’eau"},{"id":"d","texte":"La plaque plonge trop profondément"}],"multiple":false}]}$ex$::jsonb,
