  ('171ce417-ed06-5aa8-b7a7-bb6ac32075f2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le plancher de l’océan raconte son âge","competence":"raisonner","situation":"En 1912, Alfred Wegener propose que les continents dérivent. Cinquante ans plus tard, les mesures de l’âge du plancher océanique donnent raison à son idée.","documents":[{"id":"age","type":"graphique","forme":"courbe","titre":"Âge du plancher océanique selon la distance à la dorsale","categories":["0","250","500","750","1 000","1 250"],"series":[{"nom":"Âge","valeurs":[0,5,10,15,20,25],"teinte":"corail"}],"axeY":{"titre":"Âge","unite":"millions d’années","min":0,"max":30,"pas":5},"axeX":{"titre":"Distance à la dorsale (km)"},"valeurs":false,"source":"Valeurs simplifiées pour l’exercice"},{"id":"wegener","type":"texte","genre":"article","titre":"Une idée rejetée, puis confirmée","auteur":"Texte écrit pour l’exercice","blocs":["En 1912, Alfred Wegener propose que les continents se déplacent : les côtes de l’Amérique du Sud et de l’Afrique s’emboîtent, des fossiles identiques se retrouvent des deux côtés de l’Atlantique.","La plupart des géologues le rejettent : Wegener ne sait pas expliquer quelle force pourrait déplacer des continents entiers.","Dans les années 1960, la cartographie des fonds océaniques et les mesures magnétiques montrent que l’océan s’ouvre à la dorsale."]}],"questions":[{"enonce":"Lis l’âge du plancher océanique à 1 000 km de la dorsale.","aide":"Repère 1 000 sur l’axe horizontal puis monte jusqu’à la courbe.","type":"nombre","unite":"M. d’années"},{"enonce":"Calcule la vitesse d’écartement en cm par an (1 000 km en 20 millions d’années).","aide":"Convertis : 1 km = 100 000 cm, donc 1 000 km = 100 000 000 cm. Divise par 20 000 000.","type":"nombre","unite":"cm/an"},{"enonce":"Que montre l’augmentation de l’âge quand on s’éloigne de la dorsale ?","aide":"Plus on est loin de la dorsale, plus la roche est vieille.","type":"choix","options":[{"id":"a","texte":"De la lithosphère neuve se forme à la dorsale puis s’écarte de part et d’autre"},{"id":"b","texte":"Le plancher a été formé d’un seul coup"},{"id":"c","texte":"Les plaques ne bougent pas"},{"id":"d","texte":"Les roches vieillissent plus vite près de la dorsale"}],"multiple":false},{"enonce":"D’après le texte, pourquoi les géologues ont-ils d’abord rejeté l’idée de Wegener ?","aide":"Relis le deuxième paragraphe.","type":"choix","options":[{"id":"a","texte":"Il n’expliquait pas le moteur du déplacement"},{"id":"b","texte":"Il n’avait aucune observation"},{"id":"c","texte":"Les fossiles étaient différents"},{"id":"d","texte":"Les côtes ne s’emboîtaient pas"}],"multiple":false},{"enonce":"Range les étapes du recyclage de la lithosphère.","aide":"Cela commence à la dorsale et finit à la fosse.","type":"ordre","items":[{"id":"a","texte":"La plaque s’écarte de la dorsale en refroidissant"},{"id":"b","texte":"Elle rencontre une autre plaque"},{"id":"c","texte":"Du magma remonte à la dorsale et forme de la lithosphère neuve"},{"id":"d","texte":"Elle plonge dans le manteau (subduction)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 M. d’années","explication":"À 1 000 km de la dorsale, le plancher a **20 millions d’années**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 cm/an","explication":"100 000 000 cm ÷ 20 000 000 ans = **5 cm/an**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La roche la plus jeune est à la dorsale : c’est là que naît la lithosphère, qui s’écarte ensuite (**expansion océanique**)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Wegener avait des arguments, mais **aucun moteur** : il a fallu attendre la convection du manteau et l’expansion océanique."},{"cle":{"type":"ordre","ids":["c","a","b","d"]},"explication":"La lithosphère **naît** à la dorsale, voyage, puis **disparaît** en subduction : la surface se recycle."}]$ex$::jsonb),
