   $ex${"titre":"Où la roche casse","competence":"observer-schema","situation":"Lors d’un séisme, le sol vibre en surface alors que tout commence en profondeur. Un schéma en coupe montre deux points importants.","documents":[{"id":"coupe","type":"schema","titre":"Coupe du sol lors d’un séisme","largeur":320,"hauteur":220,"elements":[{"forme":"rect","x":20,"y":70,"l":280,"h":130,"teinte":"brun","motif":"clair"},{"forme":"ligne","de":[20,70],"a":[300,70],"teinte":"encre"},{"forme":"ligne","de":[160,70],"a":[160,150],"style":"pointilles","teinte":"encre"},{"forme":"cercle","cx":160,"cy":70,"r":7,"teinte":"corail","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":160,"cy":150,"r":9,"teinte":"violet","motif":"plein","id":"z2","zone":true},{"forme":"etiquette","x":240,"y":35,"texte":"A","vers":[167,66]},{"forme":"etiquette","x":240,"y":175,"texte":"B","vers":[169,152]},{"forme":"texte","x":60,"y":90,"texte":"Surface","taille":"petit","italique":true}]}],"questions":[{"enonce":"Touche le point où la roche se rompt en profondeur.","aide":"Il est en profondeur, sous la surface.","type":"zone","document":"coupe","multiple":false},{"enonce":"Touche le point de la surface situé à la verticale du foyer.","aide":"Suis la ligne pointillée vers le haut.","type":"zone","document":"coupe","multiple":false},{"enonce":"Où les dégâts sont-ils en général les plus importants ?","aide":"L’épicentre est le point de la surface le plus proche du foyer.","type":"choix","options":[{"id":"a","texte":"Au foyer, seulement"},{"id":"b","texte":"Partout de la même façon"},{"id":"c","texte":"À l’épicentre"},{"id":"d","texte":"Le plus loin possible de l’épicentre"}],"multiple":false}]}$ex$::jsonb,
