a ni sur la date.","type":"categories","categories":[{"id":"c0","texte":"Réduit la vulnérabilité"},{"id":"c1","texte":"Impossible : on ne peut pas le faire"}],"items":[{"id":"i0","texte":"Entraîner la population à se mettre à l’abri"},{"id":"i1","texte":"Empêcher le séisme de se produire"},{"id":"i2","texte":"Prédire le jour exact du prochain séisme"},{"id":"i3","texte":"Éviter de construire dans les zones les plus exposées"},{"id":"i4","texte":"Construire selon les normes parasismiques"}]},{"enonce":"Pour réduire le risque dans la ville Y, sur quoi peut-on agir ?","aide":"Regarde le graphique des bâtiments aux normes.","type":"choix","options":[{"id":"a","texte":"Sur la magnitude du prochain séisme"},{"id":"b","texte":"Sur la vulnérabilité : renforcer ou reconstruire les bâtiments"},{"id":"c","texte":"On ne peut rien faire"},{"id":"d","texte":"Sur l’aléa : calmer les failles"}],"multiple":false},{"enonce":"Pourquoi les autorités de Y ne peuvent-elles pas évacuer la ville juste avant le prochain séisme ?","aide":"Pense à la différence entre séisme et éruption.","type":"choix","options":[{"id":"a","texte":"L’évacuation est interdite"},{"id":"b","texte":"Les sismographes ne fonctionnent pas"},{"id":"c","texte":"On ne sait pas prédire la date d’un séisme"},{"id":"d","texte":"Les séismes ont toujours lieu la nuit"}],"multiple":false}]}$ex$::jsonb,
