   $ex${"titre":"Chercher sous la mer","competence":"raisonner","situation":"Une compagnie imaginaire explore une zone marine. Elle envoie des ondes sismiques dans le sous-sol et mesure le temps de retour de leurs échos, puis elle fore un puits.","documents":[{"id":"echos","type":"tableau","titre":"Échos de la sismique réflexion","colonnes":["Interface","Temps aller-retour (s)"],"lignes":[["Interface 1",0.5],["Interface 2",1],["Interface 3",1.6]],"enteteLignes":true,"source":"Vitesse moyenne des ondes : 2 000 m/s. Données imaginées"},{"id":"forage","type":"texte","genre":"article","titre":"Rapport du forage Ouest-1","auteur":"Texte écrit pour l’exercice","blocs":["À 1 600 m, un sable poreux contient un peu d’huile.","Au-dessus, le sable est perméable : aucune couche imperméable ne ferme le sable.","À 2 500 m, des marnes très riches en matière organique sont présentes."]}],"questions":[{"enonce":"Calcule la profondeur de l’interface 2.","aide":"Le temps est un aller-retour. Calcule 2 000 × 1,0 puis divise par 2.","type":"nombre","unite":"m"},{"enonce":"Calcule la profondeur de l’interface 3.","aide":"Même méthode : vitesse × temps ÷ 2.","type":"nombre","unite":"m"},{"enonce":"Pourquoi divise-t-on par 2 ?","aide":"Que mesure le temps indiqué ?","type":"choix","options":[{"id":"a","texte":"Le temps est mesuré en demi-secondes"},{"id":"b","texte":"Le son va deux fois plus vite sous terre"},{"id":"c","texte":"L’onde fait un aller-retour"},{"id":"d","texte":"Pour obtenir des kilomètres"}],"multiple":false},{"enonce":"Pourquoi ce forage ne trouve-t-il pas de gisement exploitable ?","aide":"Il y a une roche mère, un réservoir… et la suite ?","type":"choix","options":[{"id":"a","texte":"Il n’y a pas de roche mère"},{"id":"b","texte":"Il n’y a pas de sable poreux"},{"id":"c","texte":"Il n’y a pas de roche couverture imperméable pour piéger l’huile"},{"id":"d","texte":"La mer est trop profonde"}],"multiple":false},{"enonce":"Quelle affirmation sur les alternatives au pétrole est exacte ?","aide":"Pense à un « bouquet » de solutions.","type":"choix","options":[{"id":"a","texte":"Il n’existe aucune alternative"},{"id":"b","texte":"Aucune ne le remplace à elle seule : c’est leur combinaison qui compte"},{"id":"c","texte":"Le solaire suffit pour tout"},{"id":"d","texte":"Le recyclage des plastiques règle tout"}],"multiple":false}]}$ex$::jsonb,
